export function drawYugiEffect(ctx,images,kind,row,frame,x,y,scale=1,angle=0){const im=images[kind+'_vfx'];if(!im?.complete||!im.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);ctx.drawImage(im,Math.max(0,Math.min(5,frame))*512,row*384,512,384,-256,-192,512,384);ctx.restore();}
export function drawYugiSummons(ctx,images,duel){const list=duel.fighters.filter(f=>f.id==='yugi'&&f.hp>0).flatMap(f=>f.summons.map(s=>({s,f}))).sort((a,b)=>a.s.y-b.s.y);for(const {s,f} of list){const im=images[s.kind];if(!im?.complete||!im.naturalWidth)continue;const age=(duel.tick-s.born)/60,appearing=age<.5,attacking=duel.tick<(s.attackUntil||0),kur=s.kind==='kuriboh',row=appearing?(kur?1:2):kur?2:attacking?(s.kind==='dark_magician'?(s.strong?4:3):4):s.state==='run'?1:0,frame=appearing?Math.min(5,Math.floor(age*12)):attacking?Math.min(5,Math.floor((35-(s.attackUntil-duel.tick))/35*6)):Math.floor(age*9)%6,scale=kur?.7:.86;
 if(appearing)drawYugiEffect(ctx,images,s.kind,1,Math.min(4,Math.floor(age*10)),s.x,s.y,.8);ctx.save();ctx.globalAlpha=appearing?Math.min(1,.25+age*1.5):1;ctx.translate(s.x,s.y-(kur?18:0));ctx.scale(s.face<0?-1:1,1);ctx.drawImage(im,frame*320,row*224,320,224,-160*scale,-192*scale,320*scale,224*scale);ctx.restore();if(kur&&s.shield>0)drawYugiEffect(ctx,images,'kuriboh',0,3,f.x,f.y-45,.85);}}
